// An install failure, including exit zero without installing, must not cause
// an attempt from a different marketplace, even when both are available.
func TestCodexApply_DoesNotFallBack(t *testing.T) {
	for _, installErr := range []error{nil, errors.New("marketplace unavailable")} {
		var attempts []string
		provider := codexTestProvider(`{"installed":[]}`, nil, func(_ context.Context, _ string, args ...string) ([]byte, error) {
			attempts = append(attempts, args[2])
			return nil, installErr
		})

		status := provider.Detect()
		plan := provider.Plan(status, false)
		err := provider.Apply(context.Background(), nil, plan)

		require.Error(t, err)
		require.Equal(t, []string{"stripe@openai-curated"}, attempts)
		require.Contains(t, err.Error(), "openai-curated")
		require.NotContains(t, err.Error(), "openai-api-curated")
		if installErr != nil {
			require.ErrorIs(t, err, installErr)
		} else {
			require.ErrorContains(t, err, "codex reported success but stripe@openai-curated is not installed")
		}
	}
}

func TestCodexSetup_AvailableMarketplaces(t *testing.T) {
	for _, tt := range []struct {
		name        string
		listOutput  string
		marketplace string
	}{
		{
			name:        "supported order, ignoring unrelated and duplicate entries",
			listOutput:  `{"marketplaces":[{"name":"other"},{"name":"openai-api-curated"},{"name":"openai-curated"},{"name":"openai-curated"}]}`,
			marketplace: "openai-curated",
		},
		{
			name:        "ChatGPT marketplace only",
			listOutput:  `{"marketplaces":[{"name":"openai-curated"}]}`,
			marketplace: "openai-curated",
		},
		{
			name:        "API marketplace only",
			listOutput:  `{"marketplaces":[{"name":"openai-api-curated"}]}`,
			marketplace: "openai-api-curated",
		},
	} {
		t.Run(tt.name, func(t *testing.T) {
			var queried, attempts []string
			discoveries := 0
			installed := ""
			install := func(_ context.Context, name string, args ...string) ([]byte, error) {
				require.Equal(t, "codex", name)
				require.Equal(t, []string{"plugin", "add"}, args[:2])
				attempts = append(attempts, args[2])
				installed = args[2]
				return nil, nil
			}
			provider := codexTestProviderWithCustomRun(func(ctx context.Context, name string, args ...string) ([]byte, error) {
				require.Equal(t, "codex", name)
				if args[1] == "add" {
					return install(ctx, name, args...)
				}
				require.NoError(t, ctx.Err())
				if args[1] == "marketplace" {
					require.Equal(t, []string{"plugin", "marketplace", "list", "--json"}, args)
					discoveries++
					return []byte(tt.listOutput), nil
				}
				require.Equal(t, []string{"plugin", "list", "--marketplace"}, args[:3])
				require.Equal(t, "--json", args[4])
				queried = append(queried, args[3])
				if installed == "stripe@"+args[3] {
					return []byte(fmt.Sprintf(`{"installed":[{"pluginId":%q,"version":"1.0.0"}]}`, installed)), nil
				}
				return []byte(`{"installed":[]}`), nil
			})

			status := provider.Detect()
			require.Equal(t, StatusMissing, status.Status)
			require.Empty(t, status.Error)
			require.Equal(t, []string{tt.marketplace}, queried)
			pluginID := "stripe@" + tt.marketplace
			require.Equal(t, pluginID, status.Plugin.ID)
			plan := provider.Plan(status, false)
			require.Equal(t, Plan{Action: ActionInstall, Commands: [][]string{{"codex", "plugin", "add", pluginID}}}, plan)
			require.NoError(t, provider.Apply(context.Background(), nil, plan))
			require.Equal(t, []string{pluginID}, attempts)
			require.Equal(t, 1, discoveries, "Plan and Apply must reuse the selection from Detect")

			status = provider.Detect()
			require.Equal(t, StatusInstalled, status.Status)
			require.Equal(t, pluginID, status.Plugin.ID)
			require.NoError(t, provider.Apply(context.Background(), nil, provider.Plan(status, false)))
			require.Equal(t, []string{pluginID}, attempts, "skip an installed plugin")
			require.NoError(t, provider.Apply(context.Background(), nil, provider.Plan(status, true)))
			require.Equal(t, []string{pluginID, pluginID}, attempts, "force reinstalls from the detected marketplace")
			require.Equal(t, 2, discoveries, "reinstall must also reuse the selection from Detect")
		})
	}
}

func TestScanCodex_MarketplaceDiscoveryFailures(t *testing.T) {
	for _, tt := range []struct {
		name       string
		listOutput string
		listErr    error
		wantError  string
	}{
		{
			name:       "no marketplaces",
			listOutput: `{"marketplaces":[]}`,
			wantError:  "no supported Codex marketplace is available",
		},
		{
			name:       "only unrelated marketplaces",
			listOutput: `{"marketplaces":[{"name":"other"}]}`,
			wantError:  "no supported Codex marketplace is available",
		},
		{
			name:      "listing fails",
			listErr:   errors.New("marketplace listing failed"),
			wantError: "listing Codex marketplaces: marketplace listing failed",
		},
		{
			name:      "listing times out",
			listErr:   context.DeadlineExceeded,
			wantError: "listing Codex marketplaces: context deadline exceeded",
		},
		{
			name:       "invalid JSON",
			listOutput: "not JSON",
			wantError:  "listing Codex marketplaces: invalid character",
		},
	} {
		t.Run(tt.name, func(t *testing.T) {
			discoveries := 0
			provider := codexTestProviderWithCustomRun(func(_ context.Context, _ string, args ...string) ([]byte, error) {
				require.Equal(t, []string{"plugin", "marketplace", "list", "--json"}, args)
				discoveries++
				return []byte(tt.listOutput), tt.listErr
			})

			status := provider.Detect()
			require.Equal(t, StatusError, status.Status)
			require.Contains(t, status.Error, tt.wantError)
			require.Empty(t, status.Plugin.ID)
			for _, force := range []bool{false, true} {
				plan := provider.Plan(status, force)
				require.Equal(t, Plan{Action: ActionNone}, plan)
				require.NoError(t, provider.Apply(context.Background(), nil, plan))
			}
			require.Equal(t, 1, discoveries)
		})
	}
}

func codexTestProviderWithCustomRun(testCommand RunCommandFunc) CodexProvider {
	scanner := Scanner{LookPath: func(string) (string, error) { return "/usr/local/bin/codex", nil }}
	provider := NewCodexProvider(scanner, testCommand).(CodexProvider)
	return provider
}

func codexTestProvider(listOutput string, listErr error, installCommand RunCommandFunc) CodexProvider {
	return codexTestProviderWithCustomRun(func(ctx context.Context, name string, args ...string) ([]byte, error) {
		if args[1] == "add" {
			if installCommand != nil {
				return installCommand(ctx, name, args...)
			}
			return nil, nil
		}
		if listErr != nil {
			return nil, listErr
		}
		if args[1] == "marketplace" {
			return []byte(codexTestMarketplaceList), nil
		}
		return []byte(listOutput), nil
	})
}

package installmethod

import (
	"errors"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

const (
	dpkgFile  = "/var/lib/dpkg/info/stripe.list"
	yumFile   = "/etc/yum.repos.d/stripe.repo"
	dockerEnv = "/.dockerenv"
)

// marker returns the path detection looks for a stamped method at, given the
// executable it found. Built with the same expression detection uses rather than
// written out, because filepath separates with backslashes on Windows: a
// hand-written forward-slash key is never found there.
func marker(exe string) string {
	return filepath.Join(filepath.Dir(exe), methodFile)
}

// stubs describes a simulated host: the value of STRIPE_INSTALL_METHOD, where the
// executable is and what it resolves to, which files exist, what a stamped method
// file holds, and the user's home directory.
type stubs struct {
	installMethod string
	exe           string
	exeErr        bool
	links         map[string]string
	files         map[string]string
	present       []string
	home          string
}

func (s stubs) env() Env {
	return Env{
		Getenv: func(string) string { return s.installMethod },
		Executable: func() (string, error) {
			if s.exeErr {
				return "", errors.New("executable not found")
			}
			return s.exe, nil
		},
		EvalSymlinks: func(path string) (string, error) {
			if target, ok := s.links[path]; ok {
				return target, nil
			}
			return path, nil
		},
		Stat: func(path string) error {
			for _, present := range s.present {
				if present == path {
					return nil
				}
			}
			return errors.New("no such file")
		},
		ReadFile: func(path string) ([]byte, error) {
			if contents, ok := s.files[path]; ok {
				return []byte(contents), nil
			}
			return nil, errors.New("no such file")
		},
		HomeDir: func() (string, error) {
			if s.home == "" {
				return "", errors.New("no home directory")
			}
			return s.home, nil
		},
	}
}

func TestDetect(t *testing.T) {
	tests := []struct {
		name     string
		host     stubs
		expected string
	}{
		{
			name:     "npm_global via env",
			host:     stubs{installMethod: "npm_global", exe: "/usr/local/bin/stripe"},
			expected: NPMGlobal,
		},
		{
			name:     "npm_run via env",
			host:     stubs{installMethod: "npm_run", exe: "/any/path/stripe"},
			expected: NPMRun,
		},
		{
			name:     "npx via env",
			host:     stubs{installMethod: "npx", exe: "/any/path/stripe"},
			expected: NPX,
		},
		{
			name:     "env wins over every other signal",
			host:     stubs{installMethod: "npx", exe: "/opt/homebrew/Cellar/stripe/1.0/bin/stripe", present: []string{dpkgFile}},
			expected: NPX,
		},
		{
			name:     "homebrew cellar",
			host:     stubs{exe: "/opt/homebrew/Cellar/stripe/1.0/bin/stripe"},
			expected: Homebrew,
		},
		{
			name:     "homebrew apple silicon prefix, symlink unresolved",
			host:     stubs{exe: "/opt/homebrew/bin/stripe"},
			expected: Homebrew,
		},
		{
			// The Intel Mac case: os.Executable reports the launch path, which names
			// neither Cellar nor Homebrew, so only the resolved link identifies it.
			name: "homebrew intel mac, identified by resolving the symlink",
			host: stubs{
				exe:   "/usr/local/bin/stripe",
				links: map[string]string{"/usr/local/bin/stripe": "/usr/local/Cellar/stripe-cli/1.50.0/bin/stripe"},
			},
			expected: Homebrew,
		},
		{
			name:     "linuxbrew prefix",
			host:     stubs{exe: "/home/linuxbrew/.linuxbrew/bin/stripe"},
			expected: Homebrew,
		},
		{
			name:     "scoop apps directory",
			host:     stubs{exe: "C:/Users/foo/scoop/apps/stripe/current/stripe.exe"},
			expected: Scoop,
		},
		{
			name:     "scoop shim",
			host:     stubs{exe: "C:/Users/foo/scoop/shims/stripe.exe"},
			expected: Scoop,
		},
		{
			name:     "winget package directory",
			host:     stubs{exe: `C:\Users\foo\AppData\Local\Microsoft\WinGet\Packages\Stripe.StripeCLI_x\stripe.exe`},
			expected: Winget,
		},
		{
			name: "winget launcher, identified by resolving the link",
			host: stubs{
				exe: `C:\Users\foo\AppData\Local\Microsoft\WinGet\Links\stripe.exe`,
				links: map[string]string{
					`C:\Users\foo\AppData\Local\Microsoft\WinGet\Links\stripe.exe`: `C:\Users\foo\AppData\Local\Microsoft\WinGet\Packages\Stripe.StripeCLI_x\stripe.exe`,
				},
			},
			expected: Winget,
		},
		{
			name: "install script, from the method it stamped",
			host: stubs{
				exe:   "/home/user/.stripe/bin/stripe",
				files: map[string]string{marker("/home/user/.stripe/bin/stripe"): "script\n"},
			},
			expected: Script,
		},
		{
			name:     "install script in its default directory, with no stamped method",
			host:     stubs{exe: "/home/user/.stripe/bin/stripe", home: "/home/user"},
			expected: Script,
		},
		{
			name: "install script in its default directory, under a symlinked home",
			host: stubs{
				exe:   "/data/user/.stripe/bin/stripe",
				home:  "/home/user",
				links: map[string]string{filepath.Join("/home/user", ".stripe", "bin"): "/data/user/.stripe/bin"},
			},
			expected: Script,
		},
		{
			name:     "a directory that only starts like the default is not a script install",
			host:     stubs{exe: "/home/user/.stripe/binaries/stripe", home: "/home/user"},
			expected: Unknown,
		},
		{
			// STRIPE_INSTALL_DIR lets the scripts install anywhere, so the stamped
			// method is the only thing that identifies a non-default location.
			name: "install script in a custom directory",
			host: stubs{
				exe:   "/opt/tools/bin/stripe",
				files: map[string]string{marker("/opt/tools/bin/stripe"): "script"},
			},
			expected: Script,
		},
		{
			name: "stamped method beats a path heuristic",
			host: stubs{
				exe:   "/opt/homebrew/bin/stripe",
				files: map[string]string{marker("/opt/homebrew/bin/stripe"): "script"},
			},
			expected: Script,
		},
		{
			name: "stamped method from an unrecognized distributor is still reported",
			host: stubs{
				exe:   "/opt/acme/bin/stripe",
				files: map[string]string{marker("/opt/acme/bin/stripe"): "acme_internal"},
			},
			expected: "acme_internal",
		},
		{
			name: "implausible stamped method is ignored",
			host: stubs{
				exe:     "/opt/acme/bin/stripe",
				files:   map[string]string{marker("/opt/acme/bin/stripe"): "Deploy Script <v2>"},
				present: []string{dpkgFile},
			},
			expected: APT,
		},
		{
			name: "oversized stamped method is ignored",
			host: stubs{
				exe:   "/opt/acme/bin/stripe",
				files: map[string]string{marker("/opt/acme/bin/stripe"): "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"},
			},
			expected: Unknown,
		},
		{
			name:     "apt from the dpkg file list",
			host:     stubs{exe: "/usr/bin/stripe", present: []string{dpkgFile}},
			expected: APT,
		},
		{
			name:     "yum from the stripe repo",
			host:     stubs{exe: "/usr/bin/stripe", present: []string{yumFile}},
			expected: YUM,
		},
		{
			name:     "dpkg beats the weaker yum repo signal",
			host:     stubs{exe: "/usr/bin/stripe", present: []string{dpkgFile, yumFile}},
			expected: APT,
		},
		{
			name:     "docker from the official image",
			host:     stubs{exe: "/bin/stripe", present: []string{dockerEnv}},
			expected: Docker,
		},
		{
			// Our deb installs fine inside a container, and there apt is the answer.
			name:     "apt inside a container reports apt, not docker",
			host:     stubs{exe: "/usr/bin/stripe", present: []string{dpkgFile, dockerEnv}},
			expected: APT,
		},
		{
			name:     "unknown when nothing matches",
			host:     stubs{exe: "/usr/bin/stripe"},
			expected: Unknown,
		},
		{
			name:     "unknown when the executable cannot be found",
			host:     stubs{exeErr: true},
			expected: Unknown,
		},
		{
			name:     "system signals still apply when the executable cannot be found",
			host:     stubs{exeErr: true, present: []string{dpkgFile}},
			expected: APT,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			require.Equal(t, tt.expected, Detect(tt.host.env()))
		})
	}
}

func TestUpgradeAdvice(t *testing.T) {
	tests := []struct {
		name     string
		method   string
		goos     string
		expected Advice
	}{
		{"homebrew", Homebrew, "darwin", Advice{Command: "brew upgrade stripe"}},
		{"apt", APT, "linux", Advice{Command: "sudo apt update && sudo apt upgrade stripe"}},
		{"yum", YUM, "linux", Advice{Command: "sudo yum update stripe"}},
		{"scoop", Scoop, "windows", Advice{Command: "scoop update stripe"}},
		{"winget", Winget, "windows", Advice{Command: "winget upgrade Stripe.StripeCLI"}},
		{"docker", Docker, "linux", Advice{Command: "docker pull stripe/stripe-cli"}},
		{"npm global", NPMGlobal, "darwin", Advice{Command: "npm install -g @stripe/cli"}},
		{
			"install script on unix",
			Script, "darwin",
			Advice{Command: "curl -sSL https://raw.githubusercontent.com/stripe/stripe-cli/master/scripts/install.sh | sh"},
		},
		{
			"install script on windows",
			Script, "windows",
			Advice{Command: "irm https://raw.githubusercontent.com/stripe/stripe-cli/master/scripts/install.ps1 | iex"},
		},
		// npx resolves the latest version itself, so the notice is suppressed rather
		// than printed without a command.
		{"npx", NPX, "darwin", Advice{Suppress: true}},
		// The remaining methods get the notice with no command: the right upgrade
		// depends on a project's lockfile, or we could not tell how the CLI arrived.
		{"npm run", NPMRun, "darwin", Advice{}},
		{"unknown", Unknown, "linux", Advice{}},
		{"unrecognized distributor", "acme_internal", "linux", Advice{}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			require.Equal(t, tt.expected, UpgradeAdvice(tt.method, tt.goos))
		})
	}
}

func TestDetectReadsOnlyItsOwnEnvVar(t *testing.T) {
	// The detected method is reported to telemetry, and this runs on every command
	// in an environment that routinely holds keys and session identifiers. Detection
	// reads one variable by name, so assert that nothing else in the environment can
	// reach the reported value, however many variables are set.
	//
	// Deliberately not shaped like a real credential: secret scanning reads test
	// files too, and a convincing literal blocks the push.
	const secret = "[REDACTED]"

	host := stubs{exe: "/usr/bin/stripe"}
	env := host.env()
	env.Getenv = func(name string) string {
		if name == "STRIPE_INSTALL_METHOD" {
			return ""
		}
		return secret
	}

	require.Equal(t, Unknown, Detect(env))
}

